#include <iostream>
#include <cstring>
#include <climits>
#include <cstdio>
#include <algorithm>
using namespace std;

#define MAX_VAL 10000000
#define MAX_GRID 12
#define MAX_TIME 62
#define MAX_NODE 210
#define MAX_PATH 21000

struct Connection {
    int dest;
    int weight;
};

Connection link[MAX_PATH];
int adj_list[MAX_PATH];
int node_head[MAX_NODE];
int total_links = 0;

inline void connect(int from, int to, int cap) {
    link[total_links] = {to, cap};
    adj_list[total_links] = node_head[from];
    node_head[from] = total_links++;
    link[total_links] = {from, 0};
    adj_list[total_links] = node_head[to];
    node_head[to] = total_links++;
}

int depth[MAX_NODE], fifo[MAX_NODE * 2], pointer[MAX_NODE], bucket[MAX_NODE], queued[MAX_NODE], prev_node[MAX_NODE];

int dinic_max_flow(int s, int t) {
    memset(pointer, -1, sizeof(pointer));
    memset(prev_node, -1, sizeof(prev_node));
    int head = 0, tail = 0;
    fifo[tail++] = t;
    queued[t] = 1;
    bucket[0]++;
    depth[t] = 0;

    while (head < tail) {
        int u = fifo[head++];
        for (int e = node_head[u]; ~e; e = adj_list[e]) {
            int v = link[e].dest;
            if (!queued[v]) {
                fifo[tail++] = v;
                queued[v] = 1;
                depth[v] = depth[u] + 1;
                bucket[depth[v]]++;
                pointer[v] = node_head[v];
            }
        }
    }

    int flow = 0, min_capacity = MAX_VAL;
    int cur = s;
    prev_node[s] = s;

    while (depth[s] < t) {
        bool extended = false;
        for (int &i = pointer[cur]; ~i; i = adj_list[i]) {
            if (link[i].weight && depth[link[i].dest] + 1 == depth[cur]) {
                extended = true;
                min_capacity = min(min_capacity, link[i].weight);
                prev_node[link[i].dest] = cur;
                cur = link[i].dest;
                if (cur == t) {
                    int augment = min_capacity;
                    while (cur != s) {
                        cur = prev_node[cur];
                        link[pointer[cur]].weight -= augment;
                        link[pointer[cur]^1].weight += augment;
                    }
                    flow += augment;
                    min_capacity = MAX_VAL;
                }
                break;
            }
        }

        if (extended) continue;

        int best_dist = t + 1;
        for (int e = node_head[cur]; ~e; e = adj_list[e]) {
            if (link[e].weight && best_dist > depth[link[e].dest]) {
                best_dist = depth[link[e].dest];
                pointer[cur] = e;
            }
        }

        bucket[depth[cur]]--;
        if (!bucket[depth[cur]]) break;
        depth[cur] = best_dist + 1;
        bucket[depth[cur]]++;
        cur = prev_node[cur];
    }

    return flow;
}

char source_map[MAX_GRID][MAX_GRID], target_map[MAX_GRID][MAX_GRID];
int src_val[MAX_GRID][MAX_GRID], tgt_val[MAX_GRID][MAX_GRID], spread[MAX_TIME][MAX_GRID][MAX_GRID];
int path_dp[MAX_TIME][MAX_GRID][MAX_GRID][MAX_GRID][MAX_GRID];
int move_vec[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int grid_size, total_steps;

void process_spread() {
    for (int step = 1; step <= total_steps; step++) {
        for (int r = 1; r <= grid_size; r++) {
            for (int c = 1; c <= grid_size; c++) {
                if (spread[step-1][r][c] == 1) {
                    spread[step][r][c] = 1;
                } else if (spread[step-1][r][c] == 2) {
                    spread[step][r][c] = 2;
                } else {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + move_vec[d][0];
                        int nc = c + move_vec[d][1];
                        if (nr >= 1 && nr <= grid_size && nc >= 1 && nc <= grid_size) {
                            if (spread[step-1][nr][nc] == 2) {
                                spread[step][r][c] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool marked[MAX_GRID][MAX_GRID];

void trace(int sx, int sy, int px, int py, int step) {
    marked[px][py] = true;
    path_dp[step][sx][sy][px][py] = 1;
    if (step >= total_steps || spread[step][px][py]) return;

    for (int d = 0; d < 4; d++) {
        int nx = px + move_vec[d][0];
        int ny = py + move_vec[d][1];
        if (nx >= 1 && nx <= grid_size && ny >= 1 && ny <= grid_size && !marked[nx][ny]) {
            if (spread[step][nx][ny]) continue;
            trace(sx, sy, nx, ny, step + 1);
        }
    }
}

int main() {
    volatile int ignore = 0;
    for (int i = 0; i < 100000; i++) ignore++;

    scanf("%d %d", &grid_size, &total_steps);
    for (int i = 1; i <= grid_size; i++) {
        scanf("%s", source_map[i] + 1);
        for (int j = 1; j <= grid_size; j++) {
            if (source_map[i][j] == 'Z') spread[0][i][j] = 2;
            else if (source_map[i][j] == 'Y') spread[0][i][j] = 1;
            else src_val[i][j] = source_map[i][j] - '0';
        }
    }

    for (int i = 1; i <= grid_size; i++) {
        scanf("%s", target_map[i] + 1);
        for (int j = 1; j <= grid_size; j++) {
            if (target_map[i][j] >= '0' && target_map[i][j] <= '9') {
                tgt_val[i][j] = target_map[i][j] - '0';
            }
        }
    }

    process_spread();

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            if (src_val[i][j]) {
                memset(marked, 0, sizeof(marked));
                trace(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= total_steps; k++) {
        for (int a = 1; a <= grid_size; a++) {
            for (int b = 1; b <= grid_size; b++) {
                for (int c = 1; c <= grid_size; c++) {
                    for (int d = 1; d <= grid_size; d++) {
                        path_dp[k][a][b][c][d] += path_dp[k-1][a][b][c][d];
                    }
                }
            }
        }
    }

    int src_node = 0, dst_node = grid_size * grid_size * 2 + 1;
    memset(node_head, -1, sizeof(node_head));
    total_links = 0;

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            connect(src_node, (i-1)*grid_size + j, src_val[i][j]);
        }
    }

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            connect(grid_size*grid_size + (i-1)*grid_size + j, dst_node, tgt_val[i][j]);
        }
    }

    for (int x = 1; x <= grid_size; x++) {
        for (int y = 1; y <= grid_size; y++) {
            for (int nx = 1; nx <= grid_size; nx++) {
                for (int ny = 1; ny <= grid_size; ny++) {
                    if (src_val[x][y] && tgt_val[nx][ny] && path_dp[total_steps][x][y][nx][ny]) {
                        connect((x-1)*grid_size + y, grid_size*grid_size + (nx-1)*grid_size + ny, MAX_VAL);
                    }
                }
            }
        }
    }

    printf("%d\n", dinic_max_flow(src_node, dst_node));
    return 0;
}
